<section class="container page-section" id="permainan">
	<p><a class="btn btn-outline-secondary" href="<?php echo study_arena_game_url('english'); ?>"><i class="bi bi-arrow-left me-2" aria-hidden="true"></i>Kelas Bahasa Inggris</a> · <a href="<?php echo site_url('belajar/arena/riwayat'); ?>">Riwayat</a></p>
	<div class="feature-card"><p class="eyebrow"><?php echo $run['kind'] === 'lesson' ? 'Pelajaran · tanpa timer' : 'Evaluasi · tanpa timer'; ?></p><h1 class="h3"><?php echo html_escape($run['title_snapshot']); ?></h1>
	<?php if ($error): ?><div class="alert alert-danger" role="alert"><?php echo html_escape($error); ?> <a href="<?php echo site_url('belajar/arena/main/'.$run['id']); ?>">Muat ulang</a></div><?php endif; ?>
	<?php if ($run['status'] === 'running'): $step = $run['step']; ?>
	<p>Langkah <?php echo (int) $run['position'] + 1; ?> dari <?php echo (int) $run['question_count']; ?>. Progres disimpan setiap langkah.</p>
		<?php if (in_array($step['kind'], array('read', 'mission'), TRUE)): ?>
	<div class="border rounded p-3 p-md-4 my-3"><h2 class="h4" lang="en" data-english-speech><?php echo html_escape($step['english']); ?></h2><details<?php echo $run['translation'] === '1' ? ' open' : ''; ?>><summary>Arti dalam bahasa Indonesia</summary><p class="mt-2"><?php echo html_escape($step['translation']); ?></p></details><?php if ($step['note']): ?><p class="small text-secondary mt-3"><?php echo html_escape($step['note']); ?></p><?php endif; ?></div>
	<?php elseif ($step['kind'] === 'sentence'): ?><h2 class="h5">Susun kalimat Inggris sesuai arti</h2><p><?php echo html_escape($step['translation']); ?></p><p class="text-break border rounded p-3" lang="en"><?php echo html_escape($step['words']); ?></p><p class="small text-secondary">Ketik susunan dari kata-kata di atas. Tidak perlu menulis nama atau informasi pribadi. Huruf besar dan tanda baca akhir tidak memengaruhi hasil.</p>
	<?php else: ?><h2 class="h5"><?php echo html_escape($step['prompt']); ?></h2><?php endif; ?>
		<?php if ($run['audio'] === '1' && isset($step['english'])): ?><button class="btn btn-outline-secondary mb-3" type="button" data-english-listen hidden>Dengarkan contoh</button><p class="small text-secondary" data-english-audio-status>Suara opsional memakai suara Inggris lokal perangkat jika tersedia; teks tetap dapat dipelajari tanpa audio. Tidak merekam mikrofon.</p><?php endif; ?>
		<?php if ($run['feedback']): ?><div class="alert alert-info" role="status"><strong><?php echo $run['feedback']['correct'] ? 'Susunannya sesuai.' : 'Mari pelajari contohnya.'; ?></strong><p class="mb-1"><?php echo html_escape($run['feedback']['answer']); ?></p><p class="mb-0"><?php echo html_escape($run['feedback']['explanation']); ?></p></div><?php endif; ?>
		<?php echo form_open('belajar/arena/main/'.$run['id']); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>">
		<?php if ($run['feedback'] || $step['kind'] === 'read'): ?><button class="btn btn-primary" name="action" value="next">Sudah ditinjau, lanjut</button>
	<?php elseif ($step['kind'] === 'mission'): ?><input type="hidden" name="action" value="next"><div class="d-flex flex-wrap gap-2"><button class="btn btn-primary" name="value" value="practiced">Sudah mencoba</button><button class="btn btn-outline-primary" name="value" value="repeat">Perlu latihan lagi</button></div><p class="small text-secondary mt-2">Refleksi diri, tidak dinilai otomatis. Pilihanmu disimpan tanpa jawaban pribadi atau rekaman.</p>
	<?php else: ?><input type="hidden" name="action" value="answer">
		<?php if ($step['kind'] === 'choice'): ?><fieldset><legend class="h6">Pilih jawaban</legend><?php foreach ($step['options'] as $key => $label): ?><div class="form-check border rounded p-3 ps-5 mb-2"><input class="form-check-input" type="radio" id="english-<?php echo $key; ?>" name="value" value="<?php echo $key; ?>" required><label class="form-check-label text-break" for="english-<?php echo $key; ?>"><?php echo html_escape($label); ?></label></div><?php endforeach; ?></fieldset>
	<?php else: ?><label class="form-label" for="english-answer">Susunan kalimat</label><input class="form-control mb-3" id="english-answer" name="value" required maxlength="200" autocomplete="off" spellcheck="false"><?php endif; ?><button class="btn btn-primary mt-2" type="submit">Simpan jawaban</button><?php endif; ?><?php echo form_close(); ?>
	<details class="mt-4"><summary>Akhiri lebih awal</summary><p>Untuk jeda, cukup keluar dari halaman dan lanjutkan nanti. Mengakhiri lebih awal menyimpan riwayat tanpa menandai pelajaran selesai.</p><?php echo form_open('belajar/arena/main/'.$run['id']); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>"><button class="btn btn-outline-danger" name="action" value="stop">Ya, akhiri</button><?php echo form_close(); ?></details>
	<?php else: ?><h2 class="h4"><?php echo $run['status'] === 'completed' ? 'Terima kasih sudah belajar!' : 'Aktivitas diakhiri lebih awal'; ?></h2>
		<?php if ($run['kind'] === 'lesson'): ?><p><?php echo (int) $run['position']; ?>/<?php echo (int) $run['question_count']; ?> langkah ditinjau. Meninjau materi dan refleksi bicara bukan nilai penguasaan.</p><?php if ($run['graded_count']): ?><p>Latihan terarah: <?php echo (int) $run['correct_count']; ?>/<?php echo (int) $run['graded_count']; ?> jawaban sesuai dari yang sudah dikerjakan.</p><?php endif; ?>
	<?php else: ?><p><?php echo (int) $run['correct_count']; ?>/<?php echo (int) $run['question_count']; ?> jawaban benar · <?php echo (int) round($run['correct_count'] * 100 / $run['question_count']); ?>%. Ambang babak <?php echo (int) $run['passing_score']; ?>% · <?php echo $run['passed'] ? 'Ambang tercapai' : 'Belum tuntas'; ?>. Ini evaluasi materi, bukan sertifikasi bahasa.</p><?php endif; ?>
	<h3 class="h5">Tinjau kembali</h3><ol class="ps-3"><?php foreach ($run['review'] as $item): ?><li class="mb-3"><strong><?php echo html_escape($item['prompt']); ?></strong><br><?php echo html_escape($item['answer']); ?><br><span class="small text-secondary"><?php echo ! $item['visited'] ? 'Belum ditinjau' : ($item['correct'] !== NULL ? ($item['correct'] ? 'Jawaban sesuai' : 'Pelajari kembali') : ($item['reflection'] === 'repeat' ? 'Perlu latihan lagi' : 'Sudah ditinjau/dicoba')); ?></span><?php if ($item['explanation']): ?><p class="small"><?php echo html_escape($item['explanation']); ?></p><?php endif; ?></li><?php endforeach; ?></ol>
	<p class="small text-secondary">Selesai <?php echo html_escape(study_format_datetime($run['finished_at'])); ?> · versi <?php echo (int) $run['content_version']; ?>. Pengulangan tidak mengubah riwayat ini dan belum menghasilkan poin penukaran.</p><a class="btn btn-primary" href="<?php echo study_arena_game_url('english'); ?>">Pilih pelajaran berikutnya</a><?php endif; ?></div>
</section>
